1	/**
2	 * Движок раундов — общий для HTTP-ядра и testkit.
3	 *
4	 * Операции движка написаны как генераторы: каждое обращение к кошельку — это `yield` операции
5	 * (`WalletOp`), в ответ генератор получает баланс после неё. Ошибку кошелька драйвер бросает
6	 * внутрь генератора. Testkit выполняет генератор синхронно с кошельком в памяти (`runSync`),
7	 * ядро — асинхронно с HTTP-кошельком (`runAsync`). Логика раунда при этом одна.
8	 *
9	 * Сохранность денег: раунд записывается в хранилище **до** списания ставки (признак `pendingBet`)
10	 * и до выплаты (поле `pendingPayout`). Если ответ кошелька не дошёл, следующая операция с этой игрой
11	 * досылает ту же транзакцию с тем же `txId` — кошелёк идемпотентен, поэтому повтор безопасен.
12	 */
13	import type { GameModule, Rng } from '../sdk/types.ts';
14	import { PlatformError, messageOf } from '../shared/errors.ts';
15	import { LIMITS, round2 } from '../shared/money.ts';
16	
17	/** Операция с кошельком, которую запрашивает движок. Результат — баланс после операции. */
18	export type WalletOp =
19	  | { kind: 'balance' }
20	  | { kind: 'bet' | 'payout'; txId: string; roundId: string; amount: number };
21	
22	/** Генератор операции движка: отдаёт `WalletOp`, получает баланс, возвращает `T`. */
23	export type EngineGen<T> = Generator<WalletOp, T, number>;
24	
25	/** Раунд в хранилище. Параметры и состояние игры хранятся в виде JSON. */
26	export interface RoundRecord {
27	  roundId: string;
28	  gameId: string;
29	  bet: number;
30	  params: unknown;
31	  state: unknown;
32	  status: 'open' | 'closed';
33	  /** Выплата закрытого раунда, `null` пока раунд открыт. */
34	  payout: number | null;
35	  /** Списание ставки отправлено, но кошелёк его ещё не подтвердил. */
36	  pendingBet?: boolean;
37	  /** Игра завершила раунд, но выплата ещё не подтверждена кошельком. */
38	  pendingPayout: number | null;
39	  /** Раунд аннулирован (ошибка игры на старте или недосланная ставка): ставка возвращена, `view` = `null`. */
40	  voided: boolean;
41	}
42	
43	/** Ответ раунда — одинаковый у HTTP API и testkit. */
44	export interface RoundView {
45	  roundId: string;
46	  gameId: string;
47	  bet: number;
48	  status: 'open' | 'closed';
49	  view: unknown;
50	  payout: number | null;
51	  balance: number;
52	}
53	
54	/** Ответ открытия игры. */
55	export interface OpenResult {
56	  gameId: string;
57	  limits: { min: number; max: number };
58	  balance: number;
59	  activeRound: RoundView | null;
60	  /**
61	   * Раунд, который закрылся при этом открытии: досланная выплата или аннулированный раунд с недосланной ставкой.
62	   * Поля нет, если ничего не досылалось.
63	   */
64	  lastRound?: RoundView;
65	}
66	
67	/** Хранилище раундов. Методы синхронные; `get`/`findOpen` возвращают независимую копию. */
68	export interface RoundStore {
69	  get(roundId: string): RoundRecord | undefined;
70	  findOpen(gameId: string): RoundRecord | undefined;
71	  save(round: RoundRecord): void;
72	  /** Удаляет раунд, ставку которого кошелёк точно не списал. */
73	  delete(roundId: string): void;
74	}
75	
76	/** Настройки движка. */
77	export interface EngineOptions {
78	  games: GameModule[];
79	  store: RoundStore;
80	  rng: Rng;
81	  newRoundId: () => string;
82	}
83	
84	/** Движок раундов: лимиты, порядок проверок, вызовы игры, списание и выплата. */
85	export class RoundEngine {
86	  /** Подключённые игры по `id`. */
87	  readonly games: ReadonlyMap<string, GameModule>;
88	  readonly #store: RoundStore;
89	  readonly #rng: Rng;
90	  readonly #newRoundId: () => string;
91	
92	  /** @param opts игры, хранилище раундов, rng и генератор идентификаторов раундов */
93	  constructor(opts: EngineOptions) {
94	    const games = new Map<string, GameModule>();
95	    for (const g of opts.games) {
96	      if (!g || typeof g.id !== 'string') throw new TypeError('game module must have a string id');
97	      if (games.has(g.id)) throw new TypeError(`duplicate game id: ${g.id}`);
98	      games.set(g.id, g);
99	    }
100	    this.games = games;
101	    this.#store = opts.store;
102	    this.#rng = opts.rng;
103	    this.#newRoundId = opts.newRoundId;
104	  }
105	
106	  /**
107	   * Открытие игры: лимиты, баланс и незавершённый раунд.
108	   * Досылает недошедшие ставку или выплату; закрытый при этом раунд возвращается в `lastRound`.
109	   */
110	  *open(gameId: string): EngineGen<OpenResult> {
111	    this.#game(gameId);
112	    let last: RoundRecord | null = null;
113	    try {
114	      last = yield* this.#recover(gameId);
115	    } catch (e) {
116	      // Кошелёк окончательно отклонил досылку (не сбой связи): раунд остаётся ждать ручного разбора,
117	      // но open всё равно отдаёт лимиты, баланс и этот раунд с `view: null`, а не блокирует игру ошибкой.
118	      if (isUncertain(e)) throw e;
119	      const detail = e instanceof PlatformError ? `${e.code}: ${detailOf(e)}` : messageOf(e);
120	      console.error(`Досылка операции раунда игры ${gameId} отклонена кошельком, нужен ручной разбор: ${detail}`);
121	    }
122	    const round = this.#store.findOpen(gameId);
123	    const balance: number = yield { kind: 'balance' };
124	    const result: OpenResult = {
125	      gameId,
126	      limits: { min: LIMITS.min, max: LIMITS.max },
127	      balance,
128	      activeRound: round ? this.#view(round, balance, true) : null,
129	    };
130	    if (last) result.lastRound = this.#view(last, balance, true);
131	    return result;
132	  }
133	
134	  /**
135	   * Новый раунд. Порядок проверок: игра → лимиты → параметры → досылка недошедших операций → открытый раунд
136	   * → сохранение раунда → списание → `start`. Кошелёк не вызывается, пока не пройдены все проверки без денег.
137	   */
138	  *startRound(gameId: string, bet: unknown, params: unknown): EngineGen<RoundView> {
139	    const game = this.#game(gameId);
140	    const amount = checkBet(bet);
141	    const p = toJson(callGame(() => game.validateParams(params), 'INVALID_PARAMS'));
142	    yield* this.#recover(gameId);
143	    if (this.#store.findOpen(gameId)) throw new PlatformError('ROUND_ALREADY_OPEN');
144	
145	    const roundId = this.#newRoundId();
146	    const round: RoundRecord = {
147	      roundId,
148	      gameId,
149	      bet: amount,
150	      params: p,
151	      state: null,
152	      status: 'open',
153	      payout: null,
154	      pendingBet: true,
155	      pendingPayout: null,
156	      voided: false,
157	    };
158	    // Раунд записан до списания: если ответ кошелька потеряется, ставку можно будет дослать и вернуть.
159	    this.#store.save(round);
160	    let afterBet: number;
161	    try {
162	      afterBet = yield { kind: 'bet', txId: `${roundId}:bet`, roundId, amount };
163	    } catch (e) {
164	      if (!isUncertain(e)) this.#store.delete(roundId);
165	      throw e;
166	    }
167	    round.pendingBet = false;
168	
169	    let step: unknown;
170	    let state: unknown;
171	    try {
172	      step = game.start({ bet: amount, params: toJson(p), rng: this.#rng });
173	      if (isValidStep(step)) state = toJson(step.state);
174	    } catch (e) {
175	      // У раунда нет пригодного состояния, продолжать его нельзя: аннулируем и возвращаем ставку.
176	      round.voided = true;
177	      yield* this.#settle(round, amount);
178	      throw internal(`Игра ${game.id} не смогла начать раунд: ${detailOf(e)}`);
179	    }
180	    if (!isValidStep(step)) {
181	      // Ставка уже списана: раунд остаётся открытым с тем, что вернула игра (PL-19, D-023).
182	      round.state = safeJson((step as { state?: unknown } | null)?.state);
183	      this.#store.save(round);
184	      throw internal(`Игра ${game.id} вернула некорректный шаг на старте`);
185	    }
186	    return yield* this.#apply(round, step, state, afterBet);
187	  }
188	
189	  /** Ход в открытом раунде. При `INVALID_ACTION` и ошибке игры состояние раунда и баланс не меняются. */
190	  *action(roundId: string, action: unknown): EngineGen<RoundView> {
191	    const round = this.#store.get(roundId);
192	    if (!round) throw new PlatformError('ROUND_NOT_FOUND');
193	    if (round.status === 'closed') throw new PlatformError('ROUND_CLOSED');
194	    const game = this.games.get(round.gameId);
195	    if (!game) throw internal(`Игра ${round.gameId} не подключена`);
196	    if (round.pendingBet === true) {
197	      // Списание не подтверждено, игра не начиналась: досылаем ставку и аннулируем раунд.
198	      const closed = yield* this.#retryBet(round);
199	      throw new PlatformError(closed ? 'ROUND_CLOSED' : 'ROUND_NOT_FOUND');
200	    }
201	    if (round.pendingPayout !== null) {
202	      // Игра уже завершила раунд, ждём только выплату — досылаем её, ходить больше нельзя.
203	      yield* this.#settle(round, round.pendingPayout);
204	      throw new PlatformError('ROUND_CLOSED');
205	    }
206	    const step = callGame(
207	      () => game.action({ bet: round.bet, params: round.params, state: round.state, action, rng: this.#rng }),
208	      'INVALID_ACTION',
209	    );
210	    if (!isValidStep(step)) throw internal(`Игра ${game.id} вернула некорректный шаг`);
211	    const state = toJson(step.state);
212	    return yield* this.#apply(round, step, state, null);
213	  }
214	
215	  /** Досылает недошедшие ставку или выплату открытого раунда игры. Возвращает раунд, если он при этом закрылся. */
216	  *#recover(gameId: string): EngineGen<RoundRecord | null> {
217	    const round = this.#store.findOpen(gameId);
218	    if (!round) return null;
219	    if (round.pendingBet === true) return yield* this.#retryBet(round);
220	    if (round.pendingPayout !== null) {
221	      yield* this.#settle(round, round.pendingPayout);
222	      return round;
223	    }
224	    return null;
225	  }
226	
227	  /**
228	   * Повторяет списание ставки с тем же `txId`. Если кошелёк его провёл — раунд аннулируется со возвратом ставки
229	   * (игра ещё не начиналась) и возвращается закрытым. Если кошелёк точно отказал — запись удаляется, результат `null`.
230	   * Если кошелёк снова не ответил — ошибка пробрасывается, раунд остаётся в ожидании.
231	   */
232	  *#retryBet(round: RoundRecord): EngineGen<RoundRecord | null> {
233	    try {
234	      yield { kind: 'bet', txId: `${round.roundId}:bet`, roundId: round.roundId, amount: round.bet };
235	    } catch (e) {
236	      if (isUncertain(e)) throw e;
237	      this.#store.delete(round.roundId);
238	      return null;
239	    }
240	    round.pendingBet = false;
241	    round.voided = true;
242	    yield* this.#settle(round, round.bet);
243	    return round;
244	  }
245	
246	  /** Применяет корректный шаг игры: сохраняет состояние, а на `finished` — выплачивает и закрывает раунд. */
247	  *#apply(
248	    round: RoundRecord,
249	    step: { status: 'continue' } | { status: 'finished'; payout: number },
250	    state: unknown,
251	    knownBalance: number | null,
252	  ): EngineGen<RoundView> {
253	    round.state = state;
254	    if (step.status === 'continue') {
255	      this.#store.save(round);
256	      const balance: number = knownBalance ?? (yield { kind: 'balance' });
257	      return this.#view(round, balance, false);
258	    }
259	    const balance = yield* this.#settle(round, round2(step.payout));
260	    return this.#view(round, balance, false);
261	  }
262	
263	  /** Выплата `<roundId>:payout` и закрытие раунда. До ответа кошелька раунд сохранён как «ждёт выплаты». */
264	  *#settle(round: RoundRecord, amount: number): EngineGen<number> {
265	    round.pendingPayout = amount;
266	    this.#store.save(round);
267	    const balance: number = yield { kind: 'payout', txId: `${round.roundId}:payout`, roundId: round.roundId, amount };
268	    round.status = 'closed';
269	    round.payout = amount;
270	    round.pendingPayout = null;
271	    this.#store.save(round);
272	    return balance;
273	  }
274	
275	  /**
276	   * Ответ раунда. Если `publicView` игры падает, а раунд уже закрыт или ответ нужен для `open`,
277	   * отдаётся `view: null`, чтобы сломанное отображение не блокировало игру и не прятало итог раунда.
278	   */
279	  #view(round: RoundRecord, balance: number, safe: boolean): RoundView {
280	    let view: unknown = null;
281	    // Раунд, ждущий выплаты, игра уже завершила: ходов нет, показывать нечего до закрытия.
282	    if (!round.voided && round.pendingBet !== true && round.pendingPayout === null) {
283	      try {
284	        const game = this.games.get(round.gameId);
285	        if (!game) throw new Error(`Игра ${round.gameId} не подключена`);
286	        view = toJson(game.publicView(round.state, round.status === 'closed'));
287	      } catch (e) {
288	        const err = internal(`Игра ${round.gameId} не смогла показать раунд ${round.roundId}: ${detailOf(e)}`);
289	        if (!safe && round.status === 'open') throw err;
290	        console.error(`${err.code}: ${err.detail}`);
291	        view = null;
292	      }
293	    }
294	    return { roundId: round.roundId, gameId: round.gameId, bet: round.bet, status: round.status, view, payout: round.payout, balance };
295	  }
296	
297	  #game(gameId: unknown): GameModule {
298	    const game = typeof gameId === 'string' ? this.games.get(gameId) : undefined;
299	    if (!game) throw new PlatformError('GAME_NOT_FOUND');
300	    return game;
301	  }
302	}
303	
304	/** Ставка: конечное число, округлённое до центов и попадающее в лимиты. Иначе `BET_OUT_OF_LIMITS`. */
305	function checkBet(bet: unknown): number {
306	  if (typeof bet !== 'number' || !Number.isFinite(bet)) throw new PlatformError('BET_OUT_OF_LIMITS');
307	  const amount = round2(bet);
308	  if (amount < LIMITS.min || amount > LIMITS.max) throw new PlatformError('BET_OUT_OF_LIMITS');
309	  return amount;
310	}
311	
312	/** `INTERNAL_ERROR` со стандартным сообщением для клиента; подробности — только для серверного лога. */
313	function internal(detail: string): PlatformError {
314	  return new PlatformError('INTERNAL_ERROR', undefined, detail);
315	}
316	
317	function detailOf(e: unknown): string {
318	  return e instanceof PlatformError && e.detail !== undefined ? e.detail : messageOf(e);
319	}
320	
321	/**
322	 * Ошибка кошелька, после которой неизвестно, провёл ли он операцию (нет ответа, таймаут, 5xx).
323	 * Точные отказы (`INSUFFICIENT_FUNDS`, отклонённый запрос) неопределённости не оставляют.
324	 */
325	function isUncertain(e: unknown): boolean {
326	  if (!(e instanceof PlatformError)) return true;
327	  return e.code === 'WALLET_UNAVAILABLE';
328	}
329	
330	/** Вызов игры: ожидаемый код (`INVALID_PARAMS`/`INVALID_ACTION`) пробрасывается, остальное — `INTERNAL_ERROR`. */
331	function callGame<T>(fn: () => T, expected: 'INVALID_PARAMS' | 'INVALID_ACTION'): T {
332	  try {
333	    return fn();
334	  } catch (e) {
335	    const code = (e as { code?: unknown } | null)?.code;
336	    if (code === expected) {
337	      const msg = e instanceof Error && e.message && e.message !== expected ? e.message : undefined;
338	      throw new PlatformError(expected, msg);
339	    }
340	    throw internal(`Ошибка игры: ${messageOf(e)}`);
341	  }
342	}
343	
344	function isValidStep(step: unknown): step is { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number } {
345	  if (!step || typeof step !== 'object') return false;
346	  const s = step as { status?: unknown; payout?: unknown };
347	  if (s.status === 'continue') return true;
348	  return s.status === 'finished' && typeof s.payout === 'number' && Number.isFinite(s.payout) && s.payout >= 0;
349	}
350	
351	/** Копия значения через JSON — так же, как оно переживёт хранение на диске. */
352	function toJson<T>(value: T): T {
353	  if (value === undefined) return value;
354	  try {
355	    return JSON.parse(JSON.stringify(value)) as T;
356	  } catch (e) {
357	    throw internal(`Состояние игры не сериализуется в JSON: ${messageOf(e)}`);
358	  }
359	}
360	
361	function safeJson(value: unknown): unknown {
362	  try {
363	    return toJson(value);
364	  } catch {
365	    return null;
366	  }
367	}
368	
369	/** Выполняет операцию движка синхронно. `exec` выполняет операцию кошелька или бросает ошибку. */
370	export function runSync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => number): T {
371	  let r = gen.next();
372	  while (!r.done) {
373	    let balance: number;
374	    try {
375	      balance = exec(r.value);
376	    } catch (e) {
377	      r = gen.throw(e);
378	      continue;
379	    }
380	    r = gen.next(balance);
381	  }
382	  return r.value;
383	}
384	
385	/** Выполняет операцию движка асинхронно (кошелёк по HTTP). */
386	export async function runAsync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => Promise<number>): Promise<T> {
387	  let r = gen.next();
388	  while (!r.done) {
389	    let balance: number;
390	    try {
391	      balance = await exec(r.value);
392	    } catch (e) {
393	      r = gen.throw(e);
394	      continue;
395	    }
396	    r = gen.next(balance);
397	  }
398	  return r.value;
399	}
