2	 * Ядро платформы — HTTP-сервис: API раундов, оболочка `/`, интерфейсы игр `/games/<id>/` и SDK `/sdk.js`.
3	 * Раунды хранятся в `<dataDir>/rounds.json`, деньги проводятся через кошелёк по `walletUrl`.
4	 */
5	import crypto from 'node:crypto';
6	import fs from 'node:fs';
7	import http from 'node:http';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	import type { Rng } from '../sdk/types.ts';
11	import { PlatformError } from '../shared/errors.ts';
12	import { checkJsonBody, checkLocalHost, listen, readJson, sendError, sendJson, type RunningServer } from '../shared/http.ts';
13	import { RoundEngine, runAsync, type EngineGen } from './engine.ts';
14	import { loadGames, type LoadedGame } from './games.ts';
15	import { FileRoundStore } from './store.ts';
16	import { walletExecutor } from './wallet-client.ts';
17	
18	export type { RunningServer };
19	
20	const here = path.dirname(fileURLToPath(import.meta.url));
21	const SDK_FILE = path.join(here, '..', 'sdk', 'client.js');
22	const SHELL_FILE = path.join(here, 'shell.html');
23	
24	const CONTENT_TYPES: Readonly<Record<string, string>> = {
25	  '.html': 'text/html; charset=utf-8',
26	  '.js': 'text/javascript; charset=utf-8',
27	  '.mjs': 'text/javascript; charset=utf-8',
28	  '.css': 'text/css; charset=utf-8',
29	  '.json': 'application/json; charset=utf-8',
30	  '.svg': 'image/svg+xml',
31	  '.png': 'image/png',
32	  '.ico': 'image/x-icon',
33	  '.txt': 'text/plain; charset=utf-8',
34	};
