1	/**
2	 * Кошелёк партнёра — отдельный HTTP-сервис, который владеет балансом игрока `player-1`.
3	 *
4	 * - `GET /balance` → `{ balance }`
5	 * - `POST /bet { txId, roundId, amount }` → `{ balance }` или `402 INSUFFICIENT_FUNDS`
6	 * - `POST /payout { txId, roundId, amount }` → `{ balance }`
7	 *
8	 * Повтор `txId` с теми же данными возвращает сохранённый ответ, с другими — `409 TX_CONFLICT`.
9	 * Баланс и журнал хранятся в `<dataDir>/wallet.json`.
10	 *
11	 * Доступ: только локальный `Host`, без заголовка `Origin` (запрос со страницы в браузере — `403`), тело POST —
12	 * `application/json` (`415`). Если задан `token`, каждый запрос должен нести его в `x-wallet-token` (`401`).
13	 */
14	import crypto from 'node:crypto';
15	import fs from 'node:fs';
16	import http from 'node:http';
17	import path from 'node:path';
18	import { PlatformError } from '../shared/errors.ts';
19	import { checkJsonBody, checkLocalHost, listen, readJson, sendError, sendJson, type RunningServer } from '../shared/http.ts';
20	import { round2 } from '../shared/money.ts';
21	
22	export type { RunningServer };
23	
24	/** Начальный баланс игрока. */
25	export const START_BALANCE = 100;
26	/** Единственный игрок. */
27	export const PLAYER_ID = 'player-1';
28	
29	/** Запись журнала транзакций кошелька. */
30	export interface WalletTx {
31	  type: 'bet' | 'payout';
32	  roundId: string;
33	  amount: number;
34	  /** Сумма из запроса до округления — по ней повтор `txId` сравнивается с исходным. */
35	  requestedAmount?: number;
36	  /** Сохранённый ответ: повтор `txId` отдаёт его без изменений. */
37	  status: number;
38	  body: unknown;
39	}
40	
41	/** Содержимое `wallet.json`. */
42	export interface WalletState {
43	  player: string;
44	  balance: number;
45	  transactions: Record<string, WalletTx>;
46	}
47	
48	/** Настройки запуска кошелька. */
49	export interface WalletOptions {
50	  /** Порт; 0 — свободный. */
51	  port: number;
52	  /** Каталог данных, где лежит `wallet.json`. */
53	  dataDir: string;
54	  /** Адрес прослушивания; по умолчанию `127.0.0.1`. */
55	  host?: string;
56	  /** Общий секрет с ядром: запрос без него в заголовке `x-wallet-token` отклоняется с `401`. Не задан — проверки нет. */
57	  token?: string;
58	}
59	
60	/** Заголовок, в котором ядро передаёт кошельку общий секрет. */
61	export const WALLET_TOKEN_HEADER = 'x-wallet-token';
62	
63	/** Запускает HTTP-сервис кошелька. */
64	export async function startWallet(opts: WalletOptions): Promise<RunningServer> {
65	  const file = path.join(opts.dataDir, 'wallet.json');
66	  const state = loadState(file);
67	
68	  const persist = (next: WalletState): void => {
69	    fs.mkdirSync(opts.dataDir, { recursive: true });
70	    const tmp = `${file}.tmp`;
71	    fs.writeFileSync(tmp, `${JSON.stringify(next, null, 1)}\n`);
72	    fs.renameSync(tmp, file);
73	  };
74	
75	  const transact = (type: 'bet' | 'payout', input: unknown): { status: number; body: unknown } => {
76	    const { txId, roundId, amount } = (input ?? {}) as { txId?: unknown; roundId?: unknown; amount?: unknown };
77	    if (typeof txId !== 'string' || !txId || typeof roundId !== 'string' || !roundId) {
78	      throw new PlatformError('INVALID_REQUEST', 'Нужны строковые txId и roundId');
79	    }
80	    const value = typeof amount === 'number' && Number.isFinite(amount) ? round2(amount) : Number.NaN;
81	    if (!Number.isFinite(value) || (type === 'bet' ? value <= 0 : value < 0)) {
82	      return { status: 400, body: { error: { code: 'INVALID_AMOUNT', message: 'Некорректная сумма' } } };
83	    }
84	
85	    const requested = amount as number;
86	    const prev = state.transactions[txId];
87	    if (prev) {
88	      // Сравнивается сумма из запроса до округления: 2.5 и 2.504 — разные данные (у старых записей — округлённая).
89	      const prevRequested = prev.requestedAmount ?? prev.amount;
90	      if (prev.type === type && prev.roundId === roundId && prevRequested === requested) return { status: prev.status, body: prev.body };
91	      return { status: 409, body: { error: { code: 'TX_CONFLICT', message: 'txId уже использован с другими данными' } } };
92	    }
93	
94	    let balance = state.balance;
95	    let result: { status: number; body: unknown };
96	    if (type === 'bet' && value > balance) {
97	      result = { status: 402, body: { error: { code: 'INSUFFICIENT_FUNDS', message: 'Недостаточно средств' }, balance } };
98	    } else {
99	      balance = round2(type === 'bet' ? balance - value : balance + value);
100	      result = { status: 200, body: { balance } };
101	    }
102	    const tx: WalletTx = { type, roundId, amount: value, requestedAmount: requested, status: result.status, body: result.body };
103	    // Сначала диск, потом память: если запись упадёт, баланс и журнал в памяти останутся прежними.
104	    persist({ ...state, balance, transactions: { ...state.transactions, [txId]: tx } });
105	    state.balance = balance;
106	    state.transactions[txId] = tx;
107	    return result;
108	  };
109	
110	  const bindHost = opts.host ?? '127.0.0.1';
111	  const server = http.createServer(async (req, res) => {
112	    try {
113	      checkLocalHost(req, bindHost);
114	      // Кошелёк вызывает только ядро, не браузер: запрос с Origin пришёл со страницы — отклоняем.
115	      if (req.headers.origin !== undefined) throw new PlatformError('FORBIDDEN');
116	      if (opts.token !== undefined && !sameSecret(req.headers[WALLET_TOKEN_HEADER], opts.token)) {
117	        throw new PlatformError('UNAUTHORIZED');
118	      }
119	      const url = new URL(req.url ?? '/', 'http://wallet');
120	      if (req.method === 'GET' && url.pathname === '/balance') return sendJson(res, 200, { balance: state.balance });
121	      if (req.method === 'POST' && (url.pathname === '/bet' || url.pathname === '/payout')) {
122	        checkJsonBody(req);
123	        const body = await readJson(req);
124	        const r = transact(url.pathname === '/bet' ? 'bet' : 'payout', body);
125	        return sendJson(res, r.status, r.body);
126	      }
127	      throw new PlatformError('NOT_FOUND');
128	    } catch (e) {
129	      sendError(res, e);
130	    }
131	  });
132	
133	  return listen(server, opts.port, bindHost);
134	}
135	
136	/** Сравнение секрета за постоянное время. */
137	function sameSecret(got: string | string[] | undefined, expected: string): boolean {
138	  if (typeof got !== 'string') return false;
139	  const a = Buffer.from(got);
140	  const b = Buffer.from(expected);
141	  return a.length === b.length && crypto.timingSafeEqual(a, b);
142	}
143	
144	function loadState(file: string): WalletState {
145	  if (!fs.existsSync(file)) return { player: PLAYER_ID, balance: START_BALANCE, transactions: {} };
146	  // Битый файл — ошибка запуска: молча сбросить баланс игрока нельзя.
147	  const data = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<WalletState>;
148	  if (typeof data.balance !== 'number' || !Number.isFinite(data.balance)) throw new Error(`${file}: некорректный баланс`);
149	  return { player: PLAYER_ID, balance: data.balance, transactions: data.transactions ?? {} };
150	}
